module fpga_quantum_platform #(
    parameter NUM_QUBITS = 8,
    parameter DAC_BITS = 16,
    parameter PULSE_WIDTH = 20
)(
    input  wire                         clk,
    input  wire                         rst_n,
    input  wire [3:0]                   gate_type,
    input  wire [7:0]                   gate_qubit_target,
    input  wire [7:0]                   gate_qubit_control,
    input  wire [15:0]                  gate_angle,
    input  wire                         gate_valid,
    output reg                          gate_ready,
    output reg  [DAC_BITS-1:0]          i_dac [0:NUM_QUBITS-1],
    output reg  [DAC_BITS-1:0]          q_dac [0:NUM_QUBITS-1],
    output reg  [NUM_QUBITS-1:0]        meas_result,
    output reg                          meas_valid
);

localparam IDLE          = 3'd0;
localparam LOAD_GATE     = 3'd1;
localparam GENERATE_PULSE= 3'd2;
localparam WAIT_DELAY    = 3'd3;
localparam READOUT       = 3'd4;
localparam COMPLETE      = 3'd5;

reg [2:0]  state;
reg [2:0]  next_state;

reg [3:0]  cur_gate_type;
reg [7:0]  cur_gate_target;
reg [7:0]  cur_gate_control;
reg [15:0] cur_gate_angle;

reg [7:0]  pulse_counter;
reg [7:0]  delay_counter;

reg [15:0] nco_phase   [0:NUM_QUBITS-1];
reg [15:0] nco_freq    [0:NUM_QUBITS-1];
reg [15:0] amplitude   [0:NUM_QUBITS-1];

reg signed [31:0] integ_i [0:NUM_QUBITS-1];
reg signed [31:0] integ_q [0:NUM_QUBITS-1];
reg [7:0]         readout_counter;

function [15:0] cordic_cos;
    input [15:0] phase;
    begin
        cordic_cos = phase ^ 16'h8000;
    end
endfunction

function [15:0] cordic_sin;
    input [15:0] phase;
    begin
        cordic_sin = {phase[14:0], phase[15]};
    end
endfunction

integer i;

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        state <= IDLE;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    next_state = state;
    case(state)
        IDLE: begin
            if (gate_valid) next_state = LOAD_GATE;
        end
        LOAD_GATE: begin
            next_state = GENERATE_PULSE;
        end
        GENERATE_PULSE: begin
            if (pulse_counter >= PULSE_WIDTH) next_state = WAIT_DELAY;
        end
        WAIT_DELAY: begin
            if (delay_counter >= 8'd100) begin
                if (cur_gate_type == 4'd10) next_state = READOUT;
                else next_state = COMPLETE;
            end
        end
        READOUT: begin
            if (readout_counter >= 8'd200) next_state = COMPLETE;
        end
        COMPLETE: begin
            next_state = IDLE;
        end
        default: next_state = IDLE;
    endcase
end

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        gate_ready <= 1'b1;
        pulse_counter <= 8'd0;
        delay_counter <= 8'd0;
        readout_counter <= 8'd0;
        meas_valid <= 1'b0;
        meas_result <= {NUM_QUBITS{1'b0}};
        for (i=0; i<NUM_QUBITS; i=i+1) begin
            nco_phase[i] <= 16'd0;
            nco_freq[i]  <= 16'd5000 + (i[15:0] * 16'd100);
            amplitude[i] <= 16'd0;
            i_dac[i] <= {DAC_BITS{1'b0}};
            q_dac[i] <= {DAC_BITS{1'b0}};
            integ_i[i] <= 32'sd0;
            integ_q[i] <= 32'sd0;
        end
    end else begin
        case(state)
            IDLE: begin
                gate_ready <= 1'b1;
                meas_valid <= 1'b0;
                pulse_counter <= 8'd0;
                delay_counter <= 8'd0;
                readout_counter <= 8'd0;
                for (i=0; i<NUM_QUBITS; i=i+1) begin
                    amplitude[i] <= 16'd0;
                    integ_i[i] <= 32'sd0;
                    integ_q[i] <= 32'sd0;
                end
                if (gate_valid) begin
                    cur_gate_type   <= gate_type;
                    cur_gate_target <= gate_qubit_target;
                    cur_gate_control<= gate_qubit_control;
                    cur_gate_angle  <= gate_angle;
                end
            end
            LOAD_GATE: begin
                gate_ready <= 1'b0;
                pulse_counter <= 8'd0;
                delay_counter <= 8'd0;
            end
            GENERATE_PULSE: begin
                pulse_counter <= pulse_counter + 1'b1;
                for (i=0; i<NUM_QUBITS; i=i+1) begin
                    nco_phase[i] <= nco_phase[i] + nco_freq[i];
                    if (cur_gate_target == i[7:0]) begin
                        case(cur_gate_type)
                            4'd1: amplitude[i] <= 16'h7FFF;
                            4'd2: amplitude[i] <= 16'hFFFF;
                            4'd3: amplitude[i] <= 16'hFFFF;
                            4'd7: amplitude[i] <= cur_gate_angle;
                            4'd8: amplitude[i] <= cur_gate_angle;
                            default: amplitude[i] <= 16'd0;
                        endcase
                    end else begin
                        amplitude[i] <= 16'd0;
                    end
                    i_dac[i] <= (cordic_cos(nco_phase[i]) * amplitude[i]) >>> 8;
                    q_dac[i] <= (cordic_sin(nco_phase[i]) * amplitude[i]) >>> 8;
                end
            end
            WAIT_DELAY: begin
                delay_counter <= delay_counter + 1'b1;
            end
            READOUT: begin
                if (readout_counter < 8'd200) begin
                    readout_counter <= readout_counter + 1'b1;
                    for (i=0; i<NUM_QUBITS; i=i+1) begin
                        integ_i[i] <= integ_i[i] + {{16{i_dac[i][DAC_BITS-1]}}, i_dac[i]};
                        integ_q[i] <= integ_q[i] + {{16{q_dac[i][DAC_BITS-1]}}, q_dac[i]};
                    end
                    meas_valid <= 1'b0;
                end else begin
                    for (i=0; i<NUM_QUBITS; i=i+1) begin
                        if ((integ_i[i]*integ_i[i] + integ_q[i]*integ_q[i]) > 32'sd268435456)
                            meas_result[i] <= 1'b1;
                        else
                            meas_result[i] <= 1'b0;
                    end
                    meas_valid <= 1'b1;
                end
            end
            COMPLETE: begin
                gate_ready <= 1'b1;
            end
            default: begin
            end
        endcase
    end
end

endmodule
