                    photodetector_current_ua[i] <= 32'd0;
                    for (j = 0; j < MZI_ARRAY_SIZE; j = j + 1) begin
                        photodetector_current_ua[i] <= photodetector_current_ua[i] + 
                                                       mzi_out[j][i % MZI_ARRAY_SIZE];
