                processing_stage <= 8'd2;
            end

            8'd2: begin
                for (i = 0; i < NUM_WAVELENGTHS; i = i + 1) begin
                    output_data[i] <= photodetector_current_ua[i];
                end
                computation_done <= 1'b1;
                processing_stage <= 8'd0;
